async function persistRestaurantOrder(order){
 const companyId=order.companyId||activeRestaurantCompanyId()||state.settings.global?.companyId||'company_local';
 const prior=RotaMotoRestaurantOperations.findDeliveryForOrder(order,state.deliveries)||{};
 order.deliveryId=order.deliveryId||prior.id||RotaMotoContract.id('del');
 const raw=RotaMotoContract.deliveryFromOrder(order,companyId);
 const planningStatus=['CREATED','ASSIGNED','CANCELLED'].includes(order.deliveryStatus||order.canonicalStatus)?(order.deliveryStatus||order.canonicalStatus):prior.status;
 const delivery=RotaMotoRestaurantOperations.canonicalDelivery({...raw,...prior,id:order.deliveryId,orderId:order.id,companyId,status:planningStatus||'CREATED',driverId:order.bikeId||order.driverId||prior.driverId||null,updatedAt:order.updatedAt,version:Math.max(Number(order.version||0),Number(prior.version||0),1)},order,companyId);
 delivery.sync={...(prior.sync||{}),state:'local',version:Math.max(Number(order.version||0),Number(prior.sync?.version||0),1)};
 const earning=canonicalEarningFromOrder(order,companyId);
 const stores=['orders','deliveries',...(earning?['earnings']:[])],tx=db.transaction(stores,'readwrite');
 tx.objectStore('orders').put(order);tx.objectStore('deliveries').put(delivery);if(earning)tx.objectStore('earnings').put(earning);
 await new Promise((resolve,reject)=>{tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error||new Error('Falha ao salvar pedido e projeções locais.'));tx.onabort=()=>reject(tx.error||new Error('Gravação do pedido foi cancelada.'))});
 const oi=state.orders.findIndex(row=>row.id===order.id);if(oi<0)state.orders.unshift(order);else state.orders[oi]=order;
 const di=state.deliveries.findIndex(row=>row.id===delivery.id);if(di<0)state.deliveries.push(delivery);else state.deliveries[di]=delivery;
 if(earning){const ei=state.earnings.findIndex(row=>row.id===earning.id);if(ei<0)state.earnings.push(earning);else state.earnings[ei]=earning}
 return {delivery,earning};
}

