function openDB(){return new Promise((resolve,reject)=>{if(!window.indexedDB){reject(new Error('IndexedDB não está disponível neste navegador.'));return}let settled=false;const fail=e=>{if(settled)return;settled=true;reject(e instanceof Error?e:new Error(String(e||'Falha ao abrir o banco local.')))};let r;try{r=indexedDB.open(DB_NAME,DB_VERSION)}catch(e){fail(e);return}r.onupgradeneeded=event=>{try{RotaMotoStorageSchema.upgrade(r.result,r.transaction,event.oldVersion,event.newVersion)}catch(e){try{r.transaction?.abort()}catch(_){}fail(e)}};r.onsuccess=()=>{if(settled){try{r.result.close()}catch(_){}}else{settled=true;const d=r.result;d.onversionchange=()=>{try{d.close()}catch(_){}};resolve(d)}};r.onerror=()=>fail(r.error||new Error('Não foi possível abrir a base de dados local.'));r.onblocked=()=>fail(new Error('A base de dados local está sendo usada por outra aba. Feche outras abas do aplicativo e recarregue.'))});}
