   const orderChangedHere=isLocallyDirtyForSync(order);
   if(!RotaMotoRestaurantOperations.shouldGenerateDeliveryForOrder(order,!!localDelivery)){
    if(orderChangedHere)orders.push(RotaMotoRestaurantOperations.canonicalOrder(order,companyId));
    continue;
   }
   const deliveryId=order.deliveryId||localDelivery?.id||RotaMotoContract.id('del');
   if(!order.deliveryId&&orderChangedHere){order.deliveryId=deliveryId;await put('orders',order)}
   const generated=RotaMotoContract.deliveryFromOrder(order.deliveryId?order:{...order,deliveryId},companyId);
   const saved=localDelivery||{};
   const planningStatus=RotaMotoRestaurantOperations.plannedDeliveryStatus(order,saved.status,generated.status);
   const delivery=RotaMotoRestaurantOperations.canonicalDelivery({...generated,...saved,id:deliveryId,status:planningStatus},order,companyId);
   const deliveryChangedHere=localDelivery&&isLocallyDirtyForSync(localDelivery);
   if(RotaMotoRestaurantOperations.shouldIncludeDeliveryForSync({orderChangedHere,deliveryChangedHere,hasLocalDelivery:!!localDelivery,status:delivery.status}))deliveries.push(delivery);
   if(orderChangedHere)orders.push(RotaMotoRestaurantOperations.canonicalOrder(order,companyId));
