     if(window.__rotaMap!==map||!el.isConnected)return;
     if(!coords)continue;
     if(item.type==='bike'){const b=item.payload;data.bikes.push({coords,name:b.name,status:b.status||'Sem status',query:item.query,id:b.id});locatedBikes++;}
