function normalizedDeliveryRanges(ranges=[]){return (Array.isArray(ranges)?ranges:[]).map(r=>({from:Math.max(0,Number(r.from)||0),to:r.to==null||r.to===''?null:Number(r.to),value:Math.max(0,Number(r.value)||0)})).sort((a,b)=>a.from-b.from)}
function validateDeliveryRanges(ranges=[]){const rs=normalizedDeliveryRanges(ranges);for(let i=0;i<rs.length;i++){const r=rs[i];if(r.to!==null&&(!Number.isFinite(r.to)||r.to<=r.from))return {ok:false,message:`Faixa ${r.from}–${r.to} km é inválida: o limite final deve ser maior que o inicial.`};if(i>0){const prev=rs[i-1];if(prev.to===null||r.from<prev.to)return {ok:false,message:'As faixas de KM não podem se sobrepor.'}}}return {ok:true,ranges:rs}}
function calculateDeliveryFee(km, settings=state.settings){const d=settings.delivery||{};const distance=Math.max(0,Number(km)||0);const model=normalizeDeliveryModel(d.model);let base=0,detail='';if(model==='range'){const validation=validateDeliveryRanges(d.ranges||[]);if(!validation.ok)return {value:null,model,detail:validation.message,error:'invalid_ranges'};const r=validation.ranges.find(x=>distance>=x.from&&(x.to===null||distance<x.to));if(!r)return {value:null,model,detail:'Nenhuma faixa de KM cobre esta distância.',error:'no_range'};base=r.value;detail=`Faixa ${r.from}–${r.to===null?'∞':r.to} km`; }else if(model==='perDelivery'){base=Math.max(0,Number(d.fixedFee)||0);detail='Valor fixo por entrega';}else{const rate=Math.max(0,Number(d.perKm)||0);base=distance*rate;detail=`${distance.toFixed(1)} km × ${money(rate)}/km`; }let value=Math.max(Math.max(0,Number(d.minFee)||0),base);if(d.round){const step=Math.max(0.01,Number(d.roundTo)||1);value=Math.round(value/step)*step;}return {value:Number(value.toFixed(2)),model,detail};}
function deliveryModelExample(){const d=state.settings.delivery||{};const calc=calculateDeliveryFee(4.2);if(calc.value==null)return '4,2 km → nenhuma faixa válida';return `4,2 km → ${calc.detail} → ${money(calc.value)}`}
function deliveryModelStatus(){const d=state.settings.delivery||{};const model=normalizeDeliveryModel(d.model);if(model==='range'){const ranges=(d.ranges||[]).slice().sort((a,b)=>Number(a.from||0)-Number(b.from||0));if(!ranges.length)return 'Configuração incompleta: adicione pelo menos uma faixa.';const invalid=ranges.some((r,i)=>Number(r.from)<0||(r.to!=null&&Number(r.to)<=Number(r.from))||(i>0&&Number(r.from)<Number(ranges[i-1].to??Infinity)));if(invalid)return 'Revise as faixas: há limites inválidos ou sobrepostos.';if(!ranges.some(r=>Number(r.from||0)<=0))return 'Atenção: não existe faixa começando em 0 km.';return `${ranges.length} faixa(s) configurada(s). O modelo ativo é somente Por faixa de KM.`}if(model==='perDelivery'){if(Number(d.fixedFee||0)<=0)return 'Configuração incompleta: informe um valor fixo por entrega maior que zero.';return 'Modelo pronto. Cada entrega recebe o mesmo valor, independentemente da distância.'}if(Number(d.perKm||0)<=0)return 'Configuração incompleta: informe um valor por KM maior que zero.';return 'Modelo pronto. O valor é calculado pela distância × valor por KM.'}

