function setLocalSettingsSaveStatus(message,stateName='saved'){const status=document.querySelector('[data-local-save-status]');if(status){status.textContent=message;status.dataset.state=stateName;let retry=status.parentElement?.querySelector('[data-local-save-retry]');if(stateName==='error'&&!retry){retry=document.createElement('button');retry.type='button';retry.className='btn small';retry.dataset.localSaveRetry='';retry.textContent='Tentar salvar novamente';status.after(retry);retry.addEventListener('click',()=>saveSettings('Configurações locais salvas neste aparelho.').catch(()=>{}))}else if(stateName!=='error')retry?.remove()}}
async function saveSettings(message='Configurações salvas.',{feedback=true}={}){
 syncMotoboyEarningsConfig();
 const sequence=++settingsSaveSequence;
 const write=enqueueSettingsWrite(async()=>{
  const snapshot=structuredClone(state.settings);
  await setMeta('settings',snapshot);
  const persisted=await getMeta('settings');
  if(!persisted||JSON.stringify(persisted)!==JSON.stringify(snapshot))throw new Error('SETTINGS_SAVE_UNCONFIRMED');
  return true;
 });
 setLocalSettingsSaveStatus('Salvando neste aparelho…','saving');
 try{await write;if(sequence===settingsSaveSequence){localSettingsSavePending=false;setLocalSettingsSaveStatus('Salvo neste aparelho.','saved')}if(feedback){event('success',message);toast(message,'success')}return true}
 catch(error){if(sequence===settingsSaveSequence){localSettingsSavePending=true;setLocalSettingsSaveStatus('Não foi possível confirmar a gravação neste aparelho. Suas alterações continuam na tela.','error')}if(feedback)toast(error.message==='SETTINGS_SAVE_UNCONFIRMED'?'A gravação não foi confirmada. Tente novamente.':'Não foi possível salvar a configuração neste aparelho.','error');throw error}
}
async function updateSetting(el){const path=el.dataset.setting;if(!path)return;if(el.willValidate&&!el.checkValidity()){el.reportValidity();return}let value=el.value;if(el.type==='checkbox')value=el.checked;else if(el.type==='number')value=Number(value);else if(value==='true'||value==='false')value=value==='true';if(typeof value==='number'&&!Number.isFinite(value)){toast('Informe um número válido.','error');return}const parts=path.split('.');let target=state.settings;for(let i=0;i<parts.length-1;i++)target=target[parts[i]]||(target[parts[i]]={});target[parts.at(-1)]=value;if(path.startsWith('delivery.'))syncMotoboyEarningsConfig();if(['theme','accent','language'].includes(path)){applyTheme();render();try{await saveSettings('Aparência salva neste aparelho.')}catch(_){}return}try{await saveSettings('Configuração salva neste aparelho.');applyTheme();render()}catch(_){}}
