function confirmLeavingSettingsDraft(){if(localSettingsSavePending){toast('A gravação local falhou. Tente salvar novamente antes de sair desta página.','error');return false}if(!hasUnsavedSettingsDraft())return true;const leave=window.confirm('Há alterações da empresa que ainda não foram salvas. Sair e descartar o rascunho?');if(leave){companyProfileDraftDirty=false;companyTimeZoneDraftDirty=false;companyAddressDraftDirty=false;companyRouteGroupingDraftDirty=false;companyProfileFetchKey=null}return leave}
