async function processProviderLab(id,payload){if(!can('integrationLabOperate'))return toast('Seu perfil não pode operar o laboratório.','error');const cfg=providerLabCfg(id),env=payload?.order?payload:{order:payload},input=env.order||{};let raw=input;const event=providerLabEvent(id,{...input,...(env.event||{})});if(id==='keeta'&&typeof raw.message==='string'){try{raw={...JSON.parse(raw.message),...raw}}catch(_){return toast('O conteúdo do evento não está no formato esperado.','error')}}const eventId=String(event.messageId||event.id||`${id}-${Date.now()}`);if(cfg.processedEventIds.includes(eventId))return toast('Evento duplicado ignorado.','info');cfg.processedEventIds.push(eventId);const order=providerLabNormalize(id,raw,event);const existing=cfg.orders.find(o=>o.id===order.id||o.externalId===order.externalId);if(existing)Object.assign(existing,order,{createdAt:existing.createdAt||Date.now(),updatedAt:Date.now()});else cfg.orders.unshift(order);cfg.queue.push({type:'order.received',eventId,orderId:order.externalId,createdAt:Date.now(),state:'simulated'});toast(`Pedido sintético ${providerLabSpec(id).name} #${order.num} processado somente neste laboratório.`,'success');render();openProviderLab(id,order.id)}
async function transitionProviderLab(id,orderId,status){const cfg=providerLabCfg(id),o=cfg.orders.find(x=>x.id===orderId);if(!o||!can('integrationLabOperate'))return;const previous=o.externalStatus||null;o.externalStatus=status;o.status=providerLabLocalStatus(status);o.statusSource='external';o.statusUpdatedAt=Date.now();o.statusHistory=o.statusHistory||[];o.statusHistory.push({at:o.statusUpdatedAt,from:previous,to:o.status,externalStatus:status,sourceId:id});o.updatedAt=o.statusUpdatedAt;cfg.queue.push({type:'order.action',action:status,orderId:o.externalId,createdAt:Date.now(),state:'simulated'});toast(`Transição simulada localmente: ${status}.`,'info');render();openProviderLab(id,o.id)}
