 const active=state.orders.filter(order=>{if(order.deleted||order.deletedAt||!canAssignOwnDelivery(order)||order.bike||order.driverId||order.assignment?.motoboyId)return false;const status=orderPlanningStatus(order);return ['CREATED','REDELIVERY'].includes(status)&&RotaMotoContract.canTransition(status,'ASSIGNED')});
