 const operationallyEligible=driver=>{const availability=availabilityFor(driver);return administrativelyEligible(driver)&&availability?.effectiveStatus==='online'&&Date.parse(availability.leaseExpiresAt||'')>Date.now()};
 const bikes=allBikes.filter(operationallyEligible);
