 modal(`<div class="modal-title-row"><div><span class="eyebrow">Distribuição</span><h2>Distribuir corridas</h2><p>A rota de cada motoboy começa no restaurante. O GPS do motoboy é apenas informação operacional; ele não substitui a origem no restaurante.</p></div></div><div class="assignment-origin ${restaurant?'ready':'missing'}"><b>Origem da rota</b><span>${restaurant?'Restaurante configurado':'Configure o endereço do restaurante antes de otimizar'}</span></div><div class="assignment-grid"><section><div class="assignment-head"><b>Corridas disponíveis</b><span>${active.length} sem motoboy</span></div><div class="assignment-list">${active.map(o=>`<label class="assignment-row"><input type="checkbox" data-assign-order="${o.id}" ${preselectOrderId===o.id?'checked':''}><div><b>#${esc(o.num)} • ${esc(o.customer)}</b><small>${esc(o.address)} • ${Number(o.km||0).toFixed(1)} km • ${channelLabel(o.channel||'OUTRO')}</small></div><span>${statusLabel(o.status)}</span></label>`).join('')||emptyStateMarkup('Nenhuma entrega para distribuir','Não há entregas elegíveis sem motoboy neste momento. Atualize a lista depois que novos pedidos estiverem prontos.','bag','compact')}</div></section><section><div class="assignment-head"><b>Motoboys disponíveis</b><span>${bikes.length}</span></div><div class="assignment-list">${bikes.map(b=>{const l=locationInfo(b);return `<label class="assignment-row"><input type="checkbox" data-assign-bike="${b.id}" ${preselectBikeId===b.id?'checked':''}><div><b>${esc(b.name)}</b><small>${esc(l.valid?(l.fresh?'GPS atual':'GPS desatualizado'):'GPS não informado')} • ${bikeRaces(b.name,b.id).filter(o=>!['FINALIZADA','CANCELADA'].includes(o.status)).length} entregas ativas</small></div></label>`}).join('')||emptyStateMarkup(allBikes.length?'Nenhum motoboy elegível':'Nenhum motoboy cadastrado',allBikes.length?'Nenhum motoboy tem disponibilidade operacional atual confirmada.':'Cadastre um motoboy e confirme a disponibilidade antes de distribuir.','bike','compact')}</div></section></div><div class="assignment-suggestion" id="assignmentSuggestion" role="status" aria-live="polite">Selecione as entregas e o motoboy para gerar uma sugestão de distribuição.</div><div class="actions"><button class="btn" data-close>Fechar</button><button class="btn primary" id="confirmAssignment" ${!active.length||!bikes.length?'disabled':''}>Confirmar distribuição</button></div>`);
 const suggestion={orders:[],bikes:[],plans:[]};
