function canonicalOrderSaveConfirmed(order){const canonicalId=order?.sync?.canonicalId||order?.canonicalId||order?.id,operation=state.syncState.find(row=>row.id===`operation:Order:${order.id}`),record=state.syncState.find(row=>row.id===`canonical:Order:${canonicalId}`&&row.status==='canonical'&&row.payload?.id===canonicalId);if(!record||!RotaMotoSyncReconciliation.hasCurrentCanonicalAck(order,canonicalId,operation))return false;const payload=record.payload;if(activeRestaurantCompanyId()&&payload.companyId!==activeRestaurantCompanyId())return false;return ['customer','phone','address'].every(key=>String(payload[key]??'')===String(order[key]??''))&&(!Object.hasOwn(payload,'notes')||String(payload.notes??'')===String(order.obs??''))}
function custodyReturnId(delivery){return delivery?.extensions?.x_rotamoto_return_delivery_id||null}
