 const saveStatus=form?.querySelector('[data-detail-save-status]'),retrySync=form?.querySelector('#retryDetailSync'),saveButton=form?.querySelector('#saveDetailOrder');let pendingCanonicalOrder=null;const setSaveStatus=(message,kind='pending')=>{if(saveStatus){saveStatus.textContent=message;saveStatus.dataset.state=kind}};const confirmOrderSave=async candidate=>{setSaveStatus('Salvo neste aparelho. Confirmando com o servidor…','saving');try{await window.RotaMotoSync.syncNow()}catch(error){setSaveStatus('Salvo neste aparelho; o servidor ainda não confirmou. O rascunho foi preservado. Tente novamente.','error');if(retrySync)retrySync.hidden=false;if(saveButton)saveButton.disabled=true;return false}const latest=state.orders.find(row=>row.id===candidate.id)||candidate;if(canonicalOrderSaveConfirmed(latest)){pendingCanonicalOrder=null;if(retrySync)retrySync.hidden=true;if(saveButton)saveButton.disabled=false;setSaveStatus('Salvo e confirmado pelo servidor.','success');toast(`Pedido #${latest.num} salvo e confirmado.`);return true}const operation=state.syncState.find(row=>row.id===`operation:Order:${candidate.id}`);const message=operation?.status==='conflict'?'O servidor informou conflito. O rascunho permanece neste aparelho; atualize os dados canônicos antes de tentar novamente.':operation?.status==='rejected'?'O servidor recusou a alteração. O rascunho permanece neste aparelho. Revise os dados e tente novamente.':'Salvo neste aparelho; aguardando confirmação canônica do servidor.';setSaveStatus(message,operation?.status==='conflict'||operation?.status==='rejected'?'error':'pending');if(retrySync)retrySync.hidden=false;if(saveButton)saveButton.disabled=true;return false};if(form)form.onsubmit=async e=>{e.preventDefault();if(form.dataset.submitting==='true'||saveButton?.disabled)return;if(!can('edit'))return toast('Você não tem permissão para editar pedidos.','error');form.dataset.submitting='true';if(saveButton){saveButton.disabled=true;saveButton.textContent='Salvando…'}const fields=new FormData(form),base=state.orders.find(row=>row.id===o.id)||o,customer=String(fields.get('customer')||'').trim(),phone=String(fields.get('phone')||'').trim(),address=String(fields.get('address')||'').trim(),km=Number(fields.get('km'));if(!customer||!address||!Number.isFinite(km)||km<0){form.dataset.submitting='false';if(saveButton){saveButton.disabled=false;saveButton.textContent='Salvar alterações'}setSaveStatus('Revise cliente, endereço e distância para continuar.','error');return toast('Informe cliente, endereço e uma distância válida.','error')}const revision=Math.max(Number(base.version||0),Number(base.sync?.version||0))+1,next={...base,customer,phone,address,km,type:fields.get('type'),channel:fields.get('channel'),obs:String(fields.get('obs')||'').trim(),updatedAt:Date.now(),version:revision,sync:{...(base.sync||{}),state:'local',version:revision}};const fee=calculateDeliveryFee(next.km);if(fee.value!=null){next.money=RotaMotoOrderMoney.withManualDeliveryFee(next.money,fee.value,'BRL')||RotaMotoOrderMoney.fromDecimal(fee.value,'BRL','deliveryFeeMinor');next.value=fee.value;next.deliveryFee=fee.value;next.deliveryFeeModel=fee.model;next.deliveryFeeDetail=fee.detail;next.motoboyEarnings=motoboyEarningsForDelivery(next);next.motoboyEarningsShare=Number(next.deliveryFee)>0?Number((next.motoboyEarnings/next.deliveryFee).toFixed(4)):0}try{await persistRestaurantOrder(next)}catch(error){form.dataset.submitting='false';if(saveButton){saveButton.disabled=false;saveButton.textContent='Salvar alterações'}setSaveStatus('Não foi possível salvar neste aparelho. As alterações continuam no formulário; tente novamente.','error');return toast(error.message||'Não foi possível salvar o pedido.','error')}pendingCanonicalOrder=next;if(saveButton)saveButton.textContent='Salvando…';const confirmed=await confirmOrderSave(next);form.dataset.submitting='false';if(saveButton)saveButton.textContent=confirmed?'Salvar alterações':'Aguardando servidor…'};retrySync?.addEventL