function editBike(id){const b=state.bikes.find(x=>x.id===id);if(!b)return;const loc=locationInfo(b),adminStatus=String(b.status||'ACTIVE').toUpperCase(),knownAdminStatus=['ACTIVE','DISABLED'].includes(adminStatus);modal(`<h2>Editar motoboy</h2><p class="muted">Cadastro operacional do motorista. Identidade, convite e vínculo de acesso são gerenciados separadamente em Equipe. Localização e presença são fatos operacionais recebidos do Rota Moto.</p><form id="bikeEdit" class="formgrid"><label>Nome<input class="input" name="name" value="${esc(b.name)}" required></label><label>Telefone<input class="input" name="phone" type="tel" value="${esc(b.phone||'')}"></label><label>Email de contato<input class="input" name="email" type="email" value="${esc(b.email||'')}" autocomplete="email" maxlength="320"><small>Este email é um dado operacional de contato; não altera identidade, convite ou vínculo.</small></label><label>Situação do cadastro<select class="select" name="status">${knownAdminStatus?'':`<option value="${esc(adminStatus)}" selected>Situação atual mantida: ${esc(adminStatus)}</option>`}<option value="ACTIVE" ${adminStatus==='ACTIVE'?'selected':''}>Ativo</option><option value="DISABLED" ${adminStatus==='DISABLED'?'selected':''}>Inativo — acesso operacional bloqueado</option></select><small>Disponibilidade “online/offline” e entregas em andamento são estados operacionais separados.</small></label><label>Limite de entregas ativas<input class="input" name="capacityLimit" type="number" min="1" max="500" step="1" value="${esc(b.capacity?.unit==='deliveries'?b.capacity.limit:'')}" aria-describedby="driver-capacity-note"><small id="driver-capacity-note">Opcional. Em branco significa capacidade desconhecida; não configura peso ou volume.</small></label><div class="detail-state-field full"><span>Última localização conhecida</span><strong>${loc.valid?`${Number(loc.lat).toFixed(5)}, ${Number(loc.lng).toFixed(5)}`:'Sem localização'}</strong><small>${loc.at?`Atualizada ${dateFmt(loc.at)}; recebida do fluxo operacional.`:'Aguardando fato de localização do Rota Moto.'}</small></div><div class="actions full"><button class="btn" type="button" data-close>Cancelar</button><button class="btn primary">Salvar cadastro</button></div></form>`);document.querySelector('#bikeEdit').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),name=String(f.get('name')||'').trim(),email=String(f.get('email')||'').trim().toLowerCase(),capacityRaw=String(f.get('capacityLimit')||'').trim();if(email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/u.test(email))return toast('Informe um email válido ou deixe o campo vazio.','error');if(!name)return toast('Informe o nome do motoboy.','error');if(capacityRaw&&(!/^\d+$/u.test(capacityRaw)||Number(capacityRaw)<1||Number(capacityRaw)>500))return toast('Informe um limite inteiro entre 1 e 500 entregas.','error');Object.assign(b,{name,phone:String(f.get('phone')||'').trim(),email,status:f.get('status'),updatedAt:Date.now(),version:Math.max(Number(b.version||0),Number(b.sync?.version||0))+1,sync:{...(b.sync||{}),state:'local',version:Math.max(Number(b.version||0),Number(b.sync?.version||0))+1}});if(capacityRaw)b.capacity={unit:'deliveries',limit:Number(capacityRaw)};else delete b.capacity;await op(`Motoboy ${b.name} atualizado.`,()=>put('bikes',b));closeModal();render()};document.querySelector('[data-close]').onclick=closeModal}
function newOrderSource(){modal(`<h2>Adicionar origem</h2><form id="sourceForm" class="formgrid"><label>Nome exibido<input class="input" name="name" required placeholder="Ex.: Rappi"></label><label>Identificador local<input class="input" name="externalId" required placeholder="Ex.: rappi"></label><label class="full">Estado inicial<small>Estado interno usado quando a origem ainda não enviar um estado reconhecido.</small><select class="select" name="defaultStatus">${STATUS.map(st=>`<option value="${esc(st)}">${statusLabel(st)}</option>`).join('')}</select></label><div class="actions full"><button class="btn" type="button" data-close>Cancelar</button><button class="btn primary">Adicionar origem</button></div></form>`);document.querySelector('#sourceForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const id=String(f.get('externalId')).trim().toLowerCase().replace(/[^a-z0-9_-]+/g,'-');if(!id||state.settings.orders.sources.some(x=>(x.externalId||x.id)===id))return toast('Esse identificador já está em uso.','error');const src={id:uid('src'),externalId:id,name:String(f.get('name')).trim(),active:true,defaultStatus:f.get('defaultStatus'),states:{},provider:{type:'order_provider',icon:'generic'}};state.settings.orders.sources.push(src);await saveSettings(`Origem ${src.name} adicionada.`);closeModal();render()};document.querySelector('[data-close]').onclick=closeModal}
function addBike(){modal(`<h2>Novo motoboy</h2><p>Este cadastro organiza a operação. Informar um email não cria uma conta nem envia convite; o convite é uma etapa separada em Administração → Equipe.</p><form id="bikeForm" class="formgrid"><label>Nome<input class="input" name="name" autocomplete="name" required></label><label>Telefone<input class="input" name="phone" type="tel" autocomplete="tel"></label><label class="full">Email de contato (opcional)<input class="input" name="email" type="email" autocomplete="email" maxlength="320"><small>Use o email da pessoa para preencher o convite quando decidir enviá-lo.</small></label><div class="actions full"><button class="btn" type="button" data-close>Cancelar</button><button class="btn primary">Cadastrar</button></div></form>`);document.querySelector('#bikeForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),email=String(f.get('email')||'').trim().toLowerCase();if(email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/u.test(email))return toast('Informe um email válido ou deixe o campo vazio.','error');const b={id:uid('bike'),companyId:state.settings.global.companyId,name:String(f.get('name')||'').trim(),phone:String(f.get('phone')||'').trim(),...(email?{email}:{}),status:'DISPONÍVEL',today:0,location:'',latitude:null,longitude:null,coords:null,locationUpdatedAt:null,locationSource:'pending',locationAccuracy:null,presence:{inside:false},createdAt:Date.now(),updatedAt:Date.now(),sync:{state:'local',version:1}};await op(`Motoboy ${b.name} cadastrado.`,()=>put('bikes',b));state.bikes.push(b);closeModal();toast('Cadastro operacional salvo neste aparelho. O convite ainda não foi enviado.');render()};document.querySelector('[data-close]').onclick=closeModal}
function newProfile(){modal(`<h2>Novo perfil</h2><form id="profileForm" class="formgrid"><label>Nome do perfil<input class="input" name="name" required></label><label>Descrição<input class="input" name="description"></label><div class="actions full"><button class="btn" type="button" data-close>Cancelar</button><button class="btn primary">Criar perfil</button></div></form>`);document.querySelector('#profileForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const p={id:uid('profile'),companyId:state.settings.global.companyId,name:f.get('name'),description:f.get('description'),permissions:Object.fromEntries(ACTIONS.map(x=>[x,['view','create','edit'].includes(x)])),modules:Object.fromEntries(MODULES.map(x=>[x[0],true])),createdAt:Date.now(),updatedAt:Date.now(),sync:{state:'local',version:1}};await op(`Perfil ${p.name} criado.`,()=>put('profiles',p));state.profiles.push(p);closeModal();render()};document.querySelector('[data-close]').onclick=closeModal}
function duplicateProfile(id){const p=state.profiles.find(x=>x.id===id);if(!p)return;const n={...p,id:uid('profile'),companyId:state.settings.global.companyId,name:p.name+' (cópia)',createdAt:Date.now(),updatedAt:Date.now(),sync:{state:'local',version:1},permissions:{...p.permissions},modules:{...p.modules}};op(`Perfil ${n.name} criado a partir de uma cópia.`,()=>put('profiles',n)).then(()=>{state.profiles.push(n);render()})}
async function deleteProfile(id){if(id==='profile_admin')return toast('O perfil administrativo inicial não pode ser excluído.','error');if(state.users.some(u=>u.profileId===id))return toast('Não é possível excluir um perfil que ainda possui usuários.','error');const p=state.profiles.find(x=>x.id===id);if(!p)return;if(!(await confirmLocal(`Excluir o perfil ${p.name}?`)))return;state.profiles=state.profiles.filter(x=>x.id!==id);await del('profiles',id);event('success',`Perfil ${p.name} excluído.`);toast('Perfil excluído com sucesso.');render()}
function editProfile(id){const p=state.profiles.find(x=>x.id===id);if(!p)return;modal(`<h2>Editar perfil</h2><p>Defina módulos e ações disponíveis para este perfil.</p><div class="permission-help"><b>Laboratório:</b> Acesso ao laboratório permite abrir a aba. Operar laboratório permite simular pedidos, processar eventos e alterar estados.</div><form id="profileEdit" class="formgrid"><label>Nome<input class="input" name="name" value="${esc(p.name)}"></label><label>Descrição<input class="input" name="description" value="${esc(p.description||'')}"></label><div class="permission-sections full"><section class="permission-section"><div class="permission-section-head"><div><h3>Ações</h3><p>O que este perfil pode fazer.</p></div></div><div class="permission-grid">${ACTIONS.map(a=>`<label class="permission-card ${p.permissions?.[a]?'selected':''}"><input type="checkbox" data-pa="${a}" ${p.permissions?.[a]?'checked':''}><span class="permission-icon">${icon(a==='integrationLabOperate'?'flask':'shield')}</span><b>${esc(actionLabel(a))}</b></label>`).join('')}</div></section><section class="permission-section"><div class="permission-section-head"><div><h3>Módulos</h3><p>Quais áreas aparecem na navegação.</p></div></div><div class="permission-grid">${MODULES.map(m=>`<label class="permission-card ${p.modules?.[m[0]]?'selected':''}"><input type="checkbox" data-pm="${m[0]}" ${p.modules?.[m[0]]?'checked':''}><span class="permission-icon">${icon(m[1])}</span><b>${m[2]}</b></label>`).join('')}</div></section></div><div class="actions full"><button class="btn" type="button" data-close>Cancelar</button><button class="btn primary">Salvar perfil</button></div></form>`);document.querySelectorAll('#profileEdit .permission-card input').forEach(i=>i.addEventListener('change',()=>i.closest('.permission-card')?.classList.toggle('selected',i.checked)));document.querySelector('#profileEdit').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);p.name=f.get('name');p.description=f.get('description');p.permissions=Object.fromEntries(ACTIONS.map(a=>[a,document.querySelector(`[data-pa="${a}"]`).checked]));p.modules=Object.fromEntries(MODULES.map(m=>[m[0],document.querySelector(`[data-pm="${m[0]}"]`).checked]));p.updatedAt=Date.now();p.sync={state:'local',version:(p.sync?.version||0)+1};await put('profiles',p);event('success',`Perfil ${p.name} atualizado.`);toast('Perfil atualizado com sucesso.');closeModal();state.permissions=p.permissions;layout()};document.querySelector('[data-close]').onclick=closeModal}
async function toggleUser(id){const u=state.users.find(x=>x.id===id);if(!u||u.id===state.user?.id)return toast('O usuário atualmente conectado não pode ser desativado.','error');u.active=u.active===false;u.updatedAt=Date.now();u.sync={state:'local',version:(u.sync?.version||0)+1};await put('users',u);event('success',`Usuário ${u.name} ${u.active?'ativado':'desativado'}.`);toast(`Usuário ${u.active?'ativado':'desativado'}.`);render()}
